const asLogRecord = (value: unknown): Record<string, unknown> | null =>
  value !== null && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;

const redactForLog = (value: unknown, depth = 0): unknown => {
  if (depth > 4) {
    return '[max-depth]';
  }
  if (Array.isArray(value)) {
    return value.slice(0, 8).map(item => redactForLog(item, depth + 1));
  }
  if (value !== null && typeof value === 'object') {
    const output: Record<string, unknown> = {};
    Object.entries(value as Record<string, unknown>).forEach(([key, item]) => {
      output[key] = SENSITIVE_LOG_KEY.test(key)
        ? '[redacted]'
        : redactForLog(item, depth + 1);
    });
    return output;
  }
  return value;
};

const summarizePlanForLog = (item: unknown): Record<string, unknown> => {
  const plan = asLogRecord(item) ?? {};
  const meta = asLogRecord(plan.meta);
  const sellPoints = Array.isArray(meta?.sellPoints)
    ? meta.sellPoints.slice(0, 2)
    : [];
  return {
    id: plan.id,
    name: plan.name,
    displayName: plan.displayName,
    price: plan.price,
    purchasable: plan.purchasable,
    type: plan.type,
    sellPoints,
  };
};

const summarizeUserForLog = (item: unknown): Record<string, unknown> => {
  const user = asLogRecord(item) ?? {};
  const policies = Array.isArray(user.policies) ? user.policies : [];
  return {
    id: user.id,
    name: user.name,
    policies: policies.map(policy => {
      const row = asLogRecord(policy) ?? {};
      return {
        planId: row.planId,
        expirationDate: row.expirationDate,
        status: row.status ?? row.policyStatus,
      };
    }),
  };
};

const summarizeTicketForLog = (item: unknown): Record<string, unknown> => {
  const ticket = asLogRecord(item) ?? {};
  const doctor = asLogRecord(ticket.doctor);
  const patient = asLogRecord(ticket.patient);
  return {
    id: ticket.id,
    visitType: ticket.visitType,
    ticketStatus: ticket.ticketStatus,
    currentPosition: ticket.currentPosition,
    expectedCallTime: ticket.expectedCallTime,
    doctor: doctor?.name,
    patient: patient?.name,
  };
};

const summarizeForLog = (url: string, data: unknown): unknown => {
  const record = asLogRecord(data);
  const payload = record && 'data' in record ? record.data : data;

  if (url.includes('heals-pass-product/list') && Array.isArray(payload)) {
    return {
      success: record?.success,
      count: payload.length,
      items: payload.map(summarizePlanForLog),
    };
  }
  if (url.includes('/health-passport/user/') && asLogRecord(payload)) {
    return {
      success: record?.success,
      ...summarizeUserForLog(payload),
    };
  }
  if (url.includes('ticket/upcoming') && Array.isArray(payload)) {
    return {
      success: record?.success,
      count: payload.length,
      items: payload.map(summarizeTicketForLog),
    };
  }
  if (Array.isArray(payload)) {
    return {success: record?.success, count: payload.length};
  }
  if (record) {
    return {
      success: record.success,
      keys: Object.keys(record).slice(0, 12),
    };
  }
  return redactForLog(data);
};

const logApiResult = (
  config: AxiosRequestConfig | undefined,
  status: number | undefined,
  data: unknown,
): void => {
  const method = (config?.method ?? 'GET').toUpperCase();
  const rawUrl = config?.url ?? '';
  const joinedUrl = rawUrl.startsWith('http')
    ? rawUrl
    : `${config?.baseURL ?? ''}${rawUrl}`;
  const url = redactLogUrl(joinedUrl);
  let body = '[unserializable]';
  try {
    body = JSON.stringify(summarizeForLog(url, data));
  } catch {
    body = '[unserializable]';
  }
  if (body.length > 3500) {
    body = `${body.slice(0, 3500)}…`;
  }
  console.log(`[api] ${method} ${status ?? 'NO_STATUS'} ${url} ${body}`);
};

