private fun connectUpstream(host: String, port: Int): Socket? {
  if (ipv4Literal.matches(host) || host.contains(':')) {
    return open(host, InetAddress.getByName(host), port, "literal")
  }
  val key = "$host:$port"
  val cached = verifiedAddresses[key]
  if (cached != null && cached.expiresAt > System.currentTimeMillis()) {
    open(host, cached.address, port, "verified")?.let { return it }
    verifiedAddresses.remove(key)
  }

  val systemAddresses = try {
    InetAddress.getAllByName(host).toList()
  } catch (error: Exception) {
    Log.w(TAG, "system lookup failed for $host", error)
    emptyList()
  }
  for (address in systemAddresses) {
    if (certificateMatches(host, address, port)) {
      return remember(key, address, host, port, "system")
    }
  }

  val publicAddresses = publicLookup(host).filter { it !in systemAddresses }
  for (address in publicAddresses) {
    if (certificateMatches(host, address, port)) {
      return remember(key, address, host, port, "public DNS")
    }
  }

  for (address in systemAddresses + publicAddresses) {
    open(host, address, port, "unverified")?.let { return it }
  }
  return null
}

private fun remember(key: String, address: InetAddress, host: String, port: Int, source: String): Socket? {
  verifiedAddresses[key] = VerifiedAddress(address, System.currentTimeMillis() + VERIFIED_TTL_MS)
  return open(host, address, port, source)
}

private fun open(host: String, address: InetAddress, port: Int, source: String): Socket? {
  val socket = Socket()
  return try {
    socket.connect(InetSocketAddress(address, port), CONNECT_TIMEOUT_MS)
    Log.i(TAG, "connect $host -> ${address.hostAddress}:$port ($source)")
    socket
  } catch (error: Exception) {
    socket.close()
    null
  }
}

// A TLS handshake with the platform trust store and hostname check against
// the requested host. WebView repeats its own verification on the tunnel.
private fun certificateMatches(host: String, address: InetAddress, port: Int): Boolean {
  val plain = Socket()
  return try {
    plain.connect(InetSocketAddress(address, port), PROBE_TIMEOUT_MS)
    plain.soTimeout = PROBE_TIMEOUT_MS
    val factory = HttpsURLConnection.getDefaultSSLSocketFactory()
    (factory.createSocket(plain, host, port, true) as SSLSocket).use { tls ->
      tls.startHandshake()
      HttpsURLConnection.getDefaultHostnameVerifier().verify(host, tls.session)
    }
  } catch (error: Exception) {
    Log.w(TAG, "certificate check failed for $host at ${address.hostAddress}: ${error.message}")
    false
  } finally {
    try {
      plain.close()
    } catch (_: Exception) {
    }
  }
}

// Both resolvers are asked at once. When neither answers, public DNS is
// skipped for a while so networks that block outside DNS are not slowed down.
private fun publicLookup(host: String): List<InetAddress> {
  if (System.currentTimeMillis() < publicDnsPausedUntil) {
    return emptyList()
  }
  val tasks = publicResolvers.map { resolver ->
    workers.submit(Callable {
      try {
        queryA(resolver, host)
      } catch (error: Exception) {
        Log.w(TAG, "public DNS $resolver failed for $host: ${error.message}")
        emptyList()
      }
    })
  }
  val addresses = LinkedHashSet<InetAddress>()
  for (task in tasks) {
    try {
      addresses.addAll(task.get(DNS_TIMEOUT_MS + 500L, TimeUnit.MILLISECONDS))
    } catch (_: Exception) {
      task.cancel(true)
    }
  }
  if (addresses.isEmpty()) {
    publicDnsPausedUntil = System.currentTimeMillis() + PUBLIC_DNS_COOLDOWN_MS
  }
  return addresses.toList()
}

private fun queryA(resolver: String, host: String): List<InetAddress> {
  val query = dnsQuery(host) ?: return emptyList()
  DatagramSocket().use { socket ->
    socket.soTimeout = DNS_TIMEOUT_MS
    val packet = DatagramPacket(query, query.size, InetAddress.getByName(resolver), 53)
    socket.send(packet)
    val buffer = ByteArray(512)
    val response = DatagramPacket(buffer, buffer.size)
    socket.receive(response)
    return aRecords(buffer, response.length)
  }
}

