private static func resolveSystem(host: String) -> [String] {
  var hints = addrinfo(
    ai_flags: 0,
    ai_family: AF_UNSPEC,
    ai_socktype: SOCK_STREAM,
    ai_protocol: 0,
    ai_addrlen: 0,
    ai_canonname: nil,
    ai_addr: nil,
    ai_next: nil
