  sec_protocol_options_set_tls_server_name(tls.securityProtocolOptions, host)
  let connection = NWConnection(
    host: NWEndpoint.Host(address),
    port: nwPort,
    using: NWParameters(tls: tls)
  )
  let finished = DispatchSemaphore(value: 0)
  let resultLock = NSLock()
  var verified = false
  var reported = false
  let report = { (value: Bool) in
    resultLock.lock()
    if !reported {
      reported = true
      verified = value
      finished.signal()
    }
    resultLock.unlock()
  }
  connection.stateUpdateHandler = { state in
    switch state {
    case .ready:
      report(true)
    case .failed(let error), .waiting(let error):
      NSLog("WebView public DNS proxy certificate check failed for \(host) at \(address): \(error)")
      report(false)
    case .cancelled:
      report(false)
    default:
      break
    }
