  repeat(addresses.size) {
    val remaining = deadline - System.currentTimeMillis()
    if (remaining <= 0) {
      return ProbeOutcome(null, reachable)
    }
    val (address, result) = completion.poll(remaining, TimeUnit.MILLISECONDS)?.get()
      ?: return ProbeOutcome(null, reachable)
    when (result) {
      Probe.VERIFIED -> return ProbeOutcome(address, reachable)
      Probe.CERTIFICATE_FAILED -> reachable.add(address)
      Probe.UNREACHABLE -> Unit
    }
  }
  return ProbeOutcome(null, reachable)
}

