private enum Probe {
  case verified
  case certificateFailed
  case unreachable
}

// All candidates are checked at once and the first verified one wins, so a
// host with several dead addresses costs one timeout instead of one per address.
private static func probeAll(host: String, port: UInt16, addresses: [String]) -> (verified: String?, reachable: [String]) {
  if addresses.isEmpty {
    return (nil, [])
  }
  let lock = NSLock()
  let done = DispatchSemaphore(value: 0)
  var verified: String?
  var reachable: [String] = []
  var finished = 0
  for address in addresses {
    DispatchQueue.global(qos: .userInitiated).async {
      let result = certificateMatches(host: host, address: address, port: port)
      lock.lock()
      finished += 1
      switch result {
      case .verified:
        if verified == nil {
          verified = address
        }
      case .certificateFailed:
        reachable.append(address)
      case .unreachable:
        break
      }
      let complete = verified != nil || finished == addresses.count
      lock.unlock()
      if complete {
        done.signal()
      }
    }
  }
  _ = done.wait(timeout: .now() + probeTimeout * 2 + 0.5)
  lock.lock()
  defer { lock.unlock() }
  return (verified, reachable)
}

