function applyEmbeddedSafeArea() {
  var style = document.getElementById('heals-embedded-safe-area');
  if (!style) {
    // Android runs this before the document element exists; the
    // DOMContentLoaded listener below applies it once it does.
    var parent = document.head || document.documentElement;
    if (!parent) {
      return;
    }
    style = document.createElement('style');
    style.id = 'heals-embedded-safe-area';
    parent.appendChild(style);
  }

