    "proxy": [],
    "reported": False,
}
pending = {}
next_id = 1

def emit_line(line):
    print(line, flush=True)
    with lock:
        logf.write(line + "\n")
        logf.flush()

def fmt_ms(ms):
    return datetime.datetime.fromtimestamp(ms / 1000.0).strftime("%H:%M:%S.%f")[:-3]

def ws_send(sock, text):
    data = text.encode()
    n = len(data)
    mask = os.urandom(4)
    header = bytearray([0x81])
    if n < 126:
        header.append(0x80 | n)
    elif n < 65536:
        header.append(0x80 | 126)
        header += struct.pack("!H", n)
    else:
        header.append(0x80 | 127)
        header += struct.pack("!Q", n)
    masked = bytes(b ^ mask[i % 4] for i, b in enumerate(data))
    sock.sendall(bytes(header) + mask + masked)

def frame_reader(sock):
    buf = bytearray()
    frags = bytearray()
    frag_op = None
    while True:
        if len(buf) < 2:
            try:
                chunk = sock.recv(65536)
            except socket.timeout:
                yield None
                continue
            if not chunk:
                return
            buf += chunk
            continue
        b0, b1 = buf[0], buf[1]
        opcode = b0 & 0x0F
        fin = (b0 & 0x80) != 0
        masked = (b1 & 0x80) != 0
        length = b1 & 0x7F
        offset = 2
        if length == 126:
            if len(buf) < 4:
                chunk = sock.recv(65536)
                if not chunk:
                    return
                buf += chunk
                continue
            length = struct.unpack("!H", buf[2:4])[0]
            offset = 4
        elif length == 127:
            if len(buf) < 10:
                chunk = sock.recv(65536)
                if not chunk:
                    return
                buf += chunk
                continue
            length = struct.unpack("!Q", buf[2:10])[0]
            offset = 10
        mask_len = 4 if masked else 0
        need = offset + mask_len + length
        if len(buf) < need:
            try:
                chunk = sock.recv(65536)
            except socket.timeout:
                yield None
                continue
            if not chunk:
                return
            buf += chunk
            continue
        payload = bytes(buf[offset + mask_len:need])
        if masked:
            mask = bytes(buf[offset:offset + 4])
            payload = bytes(b ^ mask[i % 4] for i, b in enumerate(payload))
        del buf[:need]
        if opcode == 0x9:
            pong = bytearray([0x8A, len(payload)]) + payload
            try:
                sock.sendall(pong)
            except OSError:
                return
            continue
        if opcode == 0x8:
            return
        if opcode in (0x1, 0x2):
            frag_op = opcode
            frags = bytearray(payload)
        elif opcode == 0x0 and frag_op is not None:
            frags += payload
        else:
            continue
        if not fin or frag_op != 0x1:
            if fin:
                frags = bytearray()
                frag_op = None
            continue
        yield frags.decode("utf-8", "replace")
        frags = bytearray()
        frag_op = None

def send_method(sock, method, params=None):
    global next_id
    mid = next_id
    next_id += 1
    msg = {"id": mid, "method": method}
