def maybe_report():
    if state["reported"] or state["click_abs"] is None:
        return
    have_end = state["load_abs"] is not None or state["fcp_rel"] is not None
    waited = (time.time() - state["click_host"]) if state["click_host"] else 0
    if not have_end and waited < 20:
        return
    if state["yedpay_origin"] is None and waited < 20:
        return
    state["reported"] = True
    click = state["click_abs"]
    parts = [f"click={fmt_ms(click)}", f"text={state['click_text']!r}"]
    if state["beforeunload_abs"]:
        parts.append(f"js_before_leave={state['beforeunload_abs'] - click:.0f}ms")
    if state["yedpay_origin"]:
        parts.append(f"nav_start={state['yedpay_origin'] - click:.0f}ms")
        parts.append(f"url={state['yedpay_href'][:140]}")
    if state["fcp_rel"] is not None and state["yedpay_origin"]:
        parts.append(f"first_contentful_paint={state['yedpay_origin'] + state['fcp_rel'] - click:.0f}ms")
    if state["fp_rel"] is not None and state["yedpay_origin"]:
        parts.append(f"first_paint={state['yedpay_origin'] + state['fp_rel'] - click:.0f}ms")
    if state["dcl_abs"]:
        parts.append(f"dom_content_loaded={state['dcl_abs'] - click:.0f}ms")
    if state["load_abs"]:
        parts.append(f"load={state['load_abs'] - click:.0f}ms")
    if state["load_extra"]:
        extra = state["load_extra"]
        if extra.get("ttfb") is not None and state["yedpay_origin"]:
            parts.append(f"ttfb_from_click={state['yedpay_origin'] + extra['ttfb'] - click:.0f}ms")
        parts.append(
