        )
    if state["docs"]:
        parts.append("docs=" + " || ".join(state["docs"][:6]))
    if state["proxy"]:
        parts.append("proxy=" + " || ".join(state["proxy"][:6]))
    emit_line("RESULT " + " ".join(parts))

def handle_timing(name, abs_ms, href, extra):
    abs_ms = float(abs_ms)
    if name in ("pointerdown", "click") and state["click_abs"] is None and (is_pay_text(extra) or name == "click" and is_pay_text(extra)):
        if not is_pay_text(extra):
            return
        state["click_abs"] = abs_ms
        state["click_host"] = time.time()
        state["click_text"] = extra
        emit_line(f"PHASE click {fmt_ms(abs_ms)} text={extra!r}")
        return
    if name == "pointerdown" and state["click_abs"] is None and is_pay_text(extra):
        state["click_abs"] = abs_ms
        state["click_host"] = time.time()
        state["click_text"] = extra
        emit_line(f"PHASE click {fmt_ms(abs_ms)} text={extra!r}")
        return
    if state["click_abs"] is None:
        if name == "boot":
            return
        return
    if name == "beforeunload" and state["beforeunload_abs"] is None:
        state["beforeunload_abs"] = abs_ms
        emit_line(f"PHASE beforeunload {abs_ms - state['click_abs']:.0f}ms")
    elif name == "boot" and is_yedpay(href) and state["yedpay_origin"] is None:
        origin = abs_ms
        if extra.startswith("origin="):
            try:
                origin = float(extra.split("=", 1)[1])
            except ValueError:
                pass
        state["yedpay_origin"] = origin
        state["yedpay_href"] = href
        emit_line(f"PHASE yedpay_start {origin - state['click_abs']:.0f}ms {href[:160]}")
    elif name == "paint" and state["yedpay_origin"] and is_yedpay(href):
        kind, _, start = extra.partition(" start=")
        try:
            rel = float(start)
