            emit_line(f"PHASE fcp {state['yedpay_origin'] + rel - state['click_abs']:.0f}ms")
        elif kind == "first-paint" and state["fp_rel"] is None:
            state["fp_rel"] = rel
            emit_line(f"PHASE first_paint {state['yedpay_origin'] + rel - state['click_abs']:.0f}ms")
    elif name == "domcontentloaded" and is_yedpay(href) and state["dcl_abs"] is None:
        state["dcl_abs"] = abs_ms
        emit_line(f"PHASE dcl {abs_ms - state['click_abs']:.0f}ms")
    elif name == "load" and is_yedpay(href) and state["load_abs"] is None:
        state["load_abs"] = abs_ms
        if extra.startswith("{"):
            try:
                state["load_extra"] = json.loads(extra)
            except json.JSONDecodeError:
                pass
        emit_line(f"PHASE load {abs_ms - state['click_abs']:.0f}ms {extra}")
