def on_cdp(msg):
    method = msg.get("method")
    params = msg.get("params") or {}
    if method == "Runtime.consoleAPICalled":
        args = params.get("args") or []
        if not args:
            return
        value = args[0].get("value") if isinstance(args[0], dict) else None
        if not isinstance(value, str) or not value.startswith("HEALS_TIMING|"):
            return
        bits = value.split("|", 4)
        if len(bits) < 5:
            return
        handle_timing(bits[1], bits[2], bits[3], bits[4])
        return
    if method == "Network.requestWillBeSent":
        req = params.get("request") or {}
        url = req.get("url") or ""
        rtype = params.get("type") or ""
        if rtype == "Document" or is_yedpay(url):
            if rtype == "Document" or (state["click_abs"] and is_yedpay(url) and len(state["docs"]) < 8):
                host_ms = int(time.time() * 1000)
                rel = ""
                if state["click_host"]:
                    rel = f" +{(time.time() - state['click_host']) * 1000:.0f}ms"
                line = f"{rtype or 'req'} {url[:180]}{rel}"
                if rtype == "Document" or is_yedpay(url):
                    if len(state["docs"]) < 8 and (rtype == "Document" or is_yedpay(url)):
                        state["docs"].append(line)
                        emit_line(f"PHASE net {fmt_ms(host_ms)} {line}")
        return
    if method == "Page.frameNavigated":
        frame = params.get("frame") or {}
        if frame.get("parentId"):
            return
        url = frame.get("url") or ""
        emit_line(f"PHASE navigated {url[:180]}")
        return

def logcat_loop():
    proc = subprocess.Popen(
        ["adb", "-s", "4ae24c72", "logcat", "-T", "1", "-v", "time", "WebViewPublicDnsProxy:I", "*:S"],
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
    )
    assert proc.stdout is not None
    for line in proc.stdout:
        if "yedpay" not in line and "payment-stg" not in line:
            continue
        text = line.strip()
