private class ProbeOutcome(val verified: List<InetAddress>, val reachable: List<InetAddress>)

private enum class Probe { VERIFIED, CERTIFICATE_FAILED, UNREACHABLE }

// Candidates are checked together. After the first certificate succeeds, only
// a short grace is left for the others, so one dead address cannot hold the
// checkout behind a full timeout.
private fun probeAll(host: String, port: Int, addresses: List<InetAddress>): ProbeOutcome {
  if (addresses.isEmpty()) {
    return ProbeOutcome(emptyList(), emptyList())
  }
  val completion = ExecutorCompletionService<Pair<InetAddress, Probe>>(workers)
  addresses.forEach { address ->
    completion.submit(Callable { address to certificateMatches(host, address, port) })
  }
  val verified = ArrayList<InetAddress>()
  val reachable = ArrayList<InetAddress>()
  var firstVerifiedAt = 0L
  var pending = addresses.size
  val deadline = System.currentTimeMillis() + PROBE_TIMEOUT_MS * 2L + 500L
  while (pending > 0) {
    val now = System.currentTimeMillis()
    if (firstVerifiedAt > 0L && now - firstVerifiedAt >= VERIFIED_GRACE_MS) {
      break
    }
    val remaining = deadline - now
    if (remaining <= 0L) {
      break
    }
    val graceLeft = if (firstVerifiedAt > 0L) {
      firstVerifiedAt + VERIFIED_GRACE_MS - now
    } else {
      remaining
    }
    val completed = completion.poll(minOf(remaining, graceLeft).coerceAtLeast(1L), TimeUnit.MILLISECONDS)
      ?: continue
    pending -= 1
    val (address, result) = completed.get()
    when (result) {
      Probe.VERIFIED -> {
        verified.add(address)
        if (firstVerifiedAt == 0L) {
          firstVerifiedAt = System.currentTimeMillis()
        }
      }
      Probe.CERTIFICATE_FAILED -> reachable.add(address)
      Probe.UNREACHABLE -> Unit
    }
  }
  return ProbeOutcome(verified, reachable)
}

// A small read of the real page. The address that returns bytes first is the
// one the checkout should use; handshake time alone hides a slow pipe.
private fun chooseFastest(host: String, port: Int, addresses: List<InetAddress>): InetAddress? {
  if (addresses.isEmpty()) {
    return null
  }
  if (addresses.size == 1) {
    return addresses[0]
  }
  val completion = ExecutorCompletionService<InetAddress?>(workers)
  addresses.forEach { address ->
    completion.submit(Callable { if (readSample(host, address, port)) address else null })
  }
  val deadline = System.currentTimeMillis() + SAMPLE_TIMEOUT_MS
  repeat(addresses.size) {
    val remaining = deadline - System.currentTimeMillis()
    if (remaining <= 0L) {
      return addresses[0]
    }
    val winner = completion.poll(remaining, TimeUnit.MILLISECONDS)?.get() ?: continue
    return winner
  }
  return addresses[0]
}

private fun readSample(host: String, address: InetAddress, port: Int): Boolean {
  val plain = Socket()
  return try {
    plain.tcpNoDelay = true
    plain.connect(InetSocketAddress(address, port), SAMPLE_TIMEOUT_MS)
    plain.soTimeout = SAMPLE_TIMEOUT_MS
    val factory = HttpsURLConnection.getDefaultSSLSocketFactory()
    (factory.createSocket(plain, host, port, true) as SSLSocket).use { tls ->
      tls.soTimeout = SAMPLE_TIMEOUT_MS
      tls.startHandshake()
      if (!HttpsURLConnection.getDefaultHostnameVerifier().verify(host, tls.session)) {
        return false
      }
      val request = "GET / HTTP/1.1\r\nHost: $host\r\nConnection: close\r\n\r\n"
      tls.outputStream.write(request.toByteArray(Charsets.US_ASCII))
      tls.outputStream.flush()
      val buffer = ByteArray(4096)
      var read = 0
      while (read < SAMPLE_BYTES) {
        val count = tls.inputStream.read(buffer)
        if (count < 0) {
          break
        }
        read += count
      }
      read > 0
    }
  } catch (_: Exception) {
    false
  } finally {
    try {
      plain.close()
    } catch (_: Exception) {
    }
  }
}

private fun selectionSource(origin: String, count: Int, startedAt: Long): String {
  val elapsed = System.currentTimeMillis() - startedAt
  return if (count > 1) "$origin, fastest of $count in ${elapsed}ms" else "$origin, checked in ${elapsed}ms"
}

