// Candidates are checked together. After the first certificate succeeds, only
// a short grace is left for the others, so one dead address cannot hold the
// checkout behind a full timeout.
private static func probeAll(host: String, port: UInt16, addresses: [String]) -> (verified: [String], reachable: [String]) {
  if addresses.isEmpty {
    return ([], [])
  }
  let lock = NSLock()
  let done = DispatchSemaphore(value: 0)
  var verified: [String] = []
  var reachable: [String] = []
  var finished = 0
  var firstVerifiedAt: Date?
  for address in addresses {
    DispatchQueue.global(qos: .userInitiated).async {
      let result = certificateMatches(host: host, address: address, port: port)
      lock.lock()
      finished += 1
      switch result {
      case .verified:
        verified.append(address)
        if firstVerifiedAt == nil {
          firstVerifiedAt = Date()
        }
      case .certificateFailed:
        reachable.append(address)
      case .unreachable:
        break
      }
      let graceElapsed = firstVerifiedAt.map { Date().timeIntervalSince($0) >= 0.4 } ?? false
      let complete = finished == addresses.count || (graceElapsed && !verified.isEmpty)
      lock.unlock()
      if complete {
        done.signal()
      }
    }
  }
  _ = done.wait(timeout: .now() + probeTimeout * 2 + 0.5)
  lock.lock()
  defer { lock.unlock() }
  return (verified, reachable)
}

// A small read of the real page. The address that returns bytes first is the
// one the checkout should use; handshake time alone hides a slow pipe.
private static func chooseFastest(host: String, port: UInt16, addresses: [String]) -> String? {
  if addresses.isEmpty {
    return nil
  }
  if addresses.count == 1 {
    return addresses[0]
  }
  let lock = NSLock()
  let done = DispatchSemaphore(value: 0)
  var winner: String?
  for address in addresses {
    DispatchQueue.global(qos: .userInitiated).async {
      guard readSample(host: host, address: address, port: port) else {
        return
      }
      lock.lock()
      let first = winner == nil
      if first {
        winner = address
      }
      lock.unlock()
      if first {
        done.signal()
      }
    }
  }
  _ = done.wait(timeout: .now() + 2)
  lock.lock()
  defer { lock.unlock() }
  return winner ?? addresses[0]
}

private static func readSample(host: String, address: String, port: UInt16) -> Bool {
  guard let nwPort = NWEndpoint.Port(rawValue: port) else {
    return false
  }
  let tls = NWProtocolTLS.Options()
  sec_protocol_options_set_tls_server_name(tls.securityProtocolOptions, host)
  let connection = NWConnection(
    host: NWEndpoint.Host(address),
    port: nwPort,
    using: NWParameters(tls: tls)
  )
  let finished = DispatchSemaphore(value: 0)
  let resultLock = NSLock()
  var ok = false
  var reported = false
  let finish = { (value: Bool) in
    resultLock.lock()
    if !reported {
      reported = true
      ok = value
      finished.signal()
    }
    resultLock.unlock()
  }
  connection.stateUpdateHandler = { state in
    switch state {
    case .ready:
      let request = Data("GET / HTTP/1.1\r\nHost: \(host)\r\nConnection: close\r\n\r\n".utf8)
      connection.send(content: request, completion: .contentProcessed { error in
        if error != nil {
          finish(false)
          return
        }
        receiveSample(connection, remaining: 32 * 1024, gotBytes: false, finish: finish)
      })
    case .failed, .waiting, .cancelled:
      finish(false)
    default:
      break
    }
  }
  connection.start(queue: probeQueue)
  _ = finished.wait(timeout: .now() + 2)
  connection.cancel()
  return ok
}

private static func receiveSample(
  _ connection: NWConnection,
  remaining: Int,
  gotBytes: Bool,
  finish: @escaping (Bool) -> Void
) {
  connection.receive(minimumIncompleteLength: 1, maximumLength: min(remaining, 16 * 1024)) { data, _, isComplete, error in
    if error != nil {
      finish(false)
      return
    }
    let count = data?.count ?? 0
    let received = gotBytes || count > 0
    let left = remaining - count
    if left <= 0 || isComplete {
      finish(received)
      return
    }
    receiveSample(connection, remaining: left, gotBytes: received, finish: finish)
  }
}

