import WebViewComp from "@components/webView-comp/webView-comp.tsx";
import {useLoading} from "@components/loading-modal/loading-context.tsx";
import {WebViewNavigation} from 'react-native-webview';

const {id, payUrl} = $getPageParams(props) as { id: string, payUrl: string }
const {setLoading, setLoadingText} = useLoading();
const loadingVisibleRef = useRef(false);

input.old_string:
useEffect(
  () => {
    finishHPPurchase();

input.new_string:
const hidePageLoading = useCallback(() => {
  if (!loadingVisibleRef.current) {
    return;
  }
  loadingVisibleRef.current = false;
  setLoading(false);
}, [setLoading]);

const handleWebViewLoadEnd = useCallback((navState: WebViewNavigation) => {
  if (!navState.url || navState.url === 'about:blank') {
    return;
  }
  hidePageLoading();
}, [hidePageLoading]);

useEffect(() => {
  loadingVisibleRef.current = true;
  setLoadingText($i18n.t('loading'));
  setLoading(true);
  return () => {
    loadingVisibleRef.current = false;
    setLoading(false);
  };
}, [setLoading, setLoadingText]);

useEffect(
  () => {
    finishHPPurchase();

input.old_string:
  onShouldStartLoadWithRequest={handleRequest}
