/>

input.new_string:
  onShouldStartLoadWithRequest={handleRequest}
  onLoadEnd={(event) => {
    if (onLoadEnd && 'url' in event.nativeEvent) {
      onLoadEnd(event.nativeEvent);
    }
  }}
/>
